// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title MultiTenantVault - Cryptographic key derivation with tenant isolation
/// @notice Each tenant gets isolated key material derived from master entropy
contract MultiTenantVault {
    struct TenantSlot {
        bytes32 keyMaterial;
        address owner;
        uint256 nonce;
        bytes32 symlink; // Points to another slot for key delegation
    }

    mapping(bytes32 => TenantSlot) private slots;
    mapping(address => bytes32) private tenantIds;
    mapping(bytes32 => bool) private initialized;

    bytes32 private masterEntropy;
    address public admin;

    event SlotCreated(bytes32 indexed tenantId, address indexed owner);
    event KeyDerived(bytes32 indexed tenantId, bytes32 derivedKey);
    event SymlinkCreated(bytes32 indexed source, bytes32 indexed target);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyTenantOwner(bytes32 tenantId) {
        require(slots[tenantId].owner == msg.sender, "Not tenant owner");
        _;
    }

    constructor(bytes32 _masterEntropy) {
        admin = msg.sender;
        masterEntropy = _masterEntropy;
    }

    /// @notice Register a new tenant with isolated key material
    function registerTenant(bytes32 salt) external returns (bytes32 tenantId) {
        tenantId = keccak256(abi.encodePacked(msg.sender, salt, block.timestamp));
        require(!initialized[tenantId], "Tenant exists");

        bytes32 derivedKey = _deriveKey(tenantId, masterEntropy, 0);

        slots[tenantId] = TenantSlot({
            keyMaterial: derivedKey,
            owner: msg.sender,
            nonce: 0,
            symlink: bytes32(0)
        });

        tenantIds[msg.sender] = tenantId;
        initialized[tenantId] = true;

        emit SlotCreated(tenantId, msg.sender);
    }

    /// @notice Create a symlink from one tenant slot to another for delegation
    /// @dev Allows tenant A to reference tenant B's derived keys
    function createSymlink(bytes32 sourceTenantId, bytes32 targetTenantId) 
        external 
        onlyTenantOwner(sourceTenantId) 
    {
        require(initialized[targetTenantId], "Target not initialized");
        require(sourceTenantId != targetTenantId, "Cannot self-link");
        require(slots[targetTenantId].owner == msg.sender, "Cannot link to unowned slot");

        slots[sourceTenantId].symlink = targetTenantId;

        emit SymlinkCreated(sourceTenantId, targetTenantId);
    }

    /// @notice Resolve a slot, following symlinks
    /// @dev Follows symlink chain with depth limit
    function _resolveSlot(bytes32 tenantId) internal view returns (TenantSlot storage) {
        bytes32 current = tenantId;
        uint256 depth = 0;

        while (slots[current].symlink != bytes32(0) && depth < 5) {
            current = slots[current].symlink;
            depth++;
        }

        return slots[current];
    }

    /// @notice Derive a new key for the tenant, rotating material
    function deriveNewKey(bytes32 tenantId) 
        external 
        onlyTenantOwner(tenantId) 
        returns (bytes32 newKey) 
    {
        TenantSlot storage slot = slots[tenantId];
        slot.nonce++;

        newKey = _deriveKey(tenantId, slot.keyMaterial, slot.nonce);
        slot.keyMaterial = newKey;

        emit KeyDerived(tenantId, newKey);
    }

    /// @notice Get the current key material (only owner can read)
    function getKeyMaterial(bytes32 tenantId) 
        external 
        view 
        onlyTenantOwner(tenantId) 
        returns (bytes32) 
    {
        return slots[tenantId].keyMaterial;
    }

    /// @notice Verify a signature using tenant's key material
    function verifyWithTenantKey(
        bytes32 tenantId,
        bytes32 messageHash,
        bytes32 signature
    ) external view returns (bool) {
        require(slots[tenantId].owner == msg.sender, "Not authorized");
        bytes32 expected = keccak256(abi.encodePacked(slots[tenantId].keyMaterial, messageHash));
        return expected == signature;
    }

    /// @notice Internal key derivation using HKDF-like construction
    function _deriveKey(
        bytes32 context,
        bytes32 inputKey,
        uint256 nonce
    ) internal pure returns (bytes32) {
        // PRK = HMAC-like extraction
        bytes32 prk = keccak256(abi.encodePacked(inputKey, context));
        // OKM = HMAC-like expansion  
        bytes32 okm = keccak256(abi.encodePacked(prk, nonce, bytes1(0x01)));
        return okm;
    }

    /// @notice Admin can rotate master entropy (re-derives all active keys)
    function rotateMasterEntropy(bytes32 newEntropy) external onlyAdmin {
        masterEntropy = newEntropy;
    }

    /// @notice Remove symlink delegation
    function removeSymlink(bytes32 tenantId) 
        external 
        onlyTenantOwner(tenantId) 
    {
        slots[tenantId].symlink = bytes32(0);
    }
}
